function validate([functionId, z]) {
  if (!Number.isInteger(functionId) || functionId < 1 || functionId > 9) return 'function_id is a whole number from 1 to 9.';
  if (!Number.isInteger(z) || z < 1 || z > 100) return 'z is a whole number from 1 to 100.';
  return null;
}

