function adapt(input, solve, kit) {
  const [functionId, z] = input;
  const formulas = {
    1: (x, y) => x + y,
    2: (x, y) => x * y,
    3: (x, y) => x * x + y,
    4: (x, y) => x + y * y,
    5: (x, y) => x * x + y * y,
    6: (x, y) => (x + y) * (x + y),
    7: (x, y) => x * x * x + y * y * y,
    8: (x, y) => x * x * y,
    9: (x, y) => x * y * y,
  };
  const formula = formulas[functionId];
  // The formula stays inside this closure; the solution can only call f.
  const customfunction = Object.freeze({ f: (x, y) => formula(x, y) });
  const result = solve(customfunction, z);
  if (!Array.isArray(result)) throw new Error('findSolution must return an array of [x, y] pairs.');
  return result;
}

