function findSolution(customfunction, z) {
  const pairs = [];
  let x = 1;
  let y = z;

  while (x <= z && y >= 1) {
    const value = customfunction.f(x, y);
    if (value === z) {
      pairs.push([x, y]);
      x++;
      y--;
    } else if (value < z) {
      x++;
    } else {
      y--;
    }
  }
  return pairs;
}

