function findSolution(customfunction, z) {
  // f grows by at least 1 per step from f(1, 1) >= 1, so f(x, y) >= x + y - 1 and no answer has x or y above z.
  const found = [];
  for (let a = 1; a <= z; a++) {
    for (let b = 1; b <= z; b++) {
      if (customfunction.f(a, b) === z) found.push([a, b]);
    }
  }
  return found;
}

