function generate(rand, size) {
  const functionId = 1 + Math.floor(rand() * 9);
  if (size === 'large') return [functionId, 90 + Math.floor(rand() * 11)];
  const roll = rand();
  // Mostly any z, sometimes the smallest values, where answers are rare.
  const z = roll < 0.2 ? 1 + Math.floor(rand() * 4) : 1 + Math.floor(rand() * 100);
  return [functionId, z];
}
